-- mistri store layout: flags, postgres, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
CREATE SCHEMA mistri;
CREATE FUNCTION mistri.flag_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN RAISE EXCEPTION 'Flag control metadata and audit are append-only.'; END$$;
SET default_tablespace = '';
SET default_table_access_method = heap;
CREATE TABLE mistri.flag_audit (
    suite_id text NOT NULL COLLATE pg_catalog."C",
    deployment_id text NOT NULL COLLATE pg_catalog."C",
    app_id text NOT NULL COLLATE pg_catalog."C",
    environment text NOT NULL COLLATE pg_catalog."C",
    tenant_key text NOT NULL COLLATE pg_catalog."C",
    revision bigint NOT NULL,
    flag_id text NOT NULL COLLATE pg_catalog."C",
    operation text NOT NULL,
    actor_id text NOT NULL COLLATE pg_catalog."C",
    reason text NOT NULL,
    at text NOT NULL,
    revert_revision bigint,
    before_snapshot text NOT NULL,
    after_snapshot text NOT NULL,
    decision_evidence text,
    CONSTRAINT flag_audit_after_snapshot_check CHECK ((octet_length(after_snapshot) <= 1048576)),
    CONSTRAINT flag_audit_before_snapshot_check CHECK ((octet_length(before_snapshot) <= 1048576)),
    CONSTRAINT flag_audit_check CHECK (((operation = 'decide'::text) = (decision_evidence IS NOT NULL))),
    CONSTRAINT flag_audit_decision_evidence_check CHECK ((octet_length(decision_evidence) <= 1048576)),
    CONSTRAINT flag_audit_operation_check CHECK ((operation = ANY (ARRAY['set'::text, 'kill'::text, 'revert'::text, 'decide'::text]))),
    CONSTRAINT flag_audit_revision_check CHECK (((revision > 0) AND (revision <= '9007199254740991'::bigint)))
);
CREATE TABLE mistri.flag_binding (
    singleton integer NOT NULL,
    version integer NOT NULL,
    suite_id text NOT NULL COLLATE pg_catalog."C",
    deployment_id text NOT NULL COLLATE pg_catalog."C",
    CONSTRAINT flag_binding_singleton_check CHECK ((singleton = 1)),
    CONSTRAINT flag_binding_version_check CHECK ((version = 1))
);
CREATE TABLE mistri.flag_state (
    suite_id text NOT NULL COLLATE pg_catalog."C",
    deployment_id text NOT NULL COLLATE pg_catalog."C",
    app_id text NOT NULL COLLATE pg_catalog."C",
    environment text NOT NULL COLLATE pg_catalog."C",
    tenant_key text NOT NULL COLLATE pg_catalog."C",
    revision bigint NOT NULL,
    snapshot text NOT NULL,
    CONSTRAINT flag_state_revision_check CHECK (((revision >= 0) AND (revision <= '9007199254740991'::bigint))),
    CONSTRAINT flag_state_snapshot_check CHECK ((octet_length(snapshot) <= 1048576))
);
INSERT INTO mistri.flag_binding (singleton, version, suite_id, deployment_id) VALUES (1, 1, 'layout-suite', 'layout-deployment');
ALTER TABLE ONLY mistri.flag_audit
    ADD CONSTRAINT flag_audit_pkey PRIMARY KEY (suite_id, deployment_id, app_id, environment, tenant_key, revision);
ALTER TABLE ONLY mistri.flag_binding
    ADD CONSTRAINT flag_binding_pkey PRIMARY KEY (singleton);
ALTER TABLE ONLY mistri.flag_state
    ADD CONSTRAINT flag_state_pkey PRIMARY KEY (suite_id, deployment_id, app_id, environment, tenant_key);
CREATE TRIGGER flag_audit_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON mistri.flag_audit FOR EACH STATEMENT EXECUTE FUNCTION mistri.flag_immutable();
CREATE TRIGGER flag_binding_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON mistri.flag_binding FOR EACH STATEMENT EXECUTE FUNCTION mistri.flag_immutable();
